export function mergeSort<T>(xs: T[], cmp: (x: T, y: T) => number): T[] {
  if (xs.length <= 1) return xs.slice();
  const mid = xs.length >> 1;
  const left = mergeSort(xs.slice(0, mid), cmp);
  const right = mergeSort(xs.slice(mid), cmp);
  return merge(left, right, cmp);
}

use crate::merge::merge;

/// Stable merge sort — split, sort halves, merge.
pub fn merge_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    if xs.len() <= 1 {
        return xs.to_vec();
    }
    let mid = xs.len() / 2;
    let left = merge_sort(&xs[..mid]);
    let right = merge_sort(&xs[mid..]);
    merge(&left, &right)
}

export function binarySearch<T>(xs: T[], target: T, cmp: (x: T, y: T) => number): number {
  let lo = 0, hi = xs.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const c = cmp(xs[mid], target);
    if (c === 0) return mid;
    if (c < 0) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

/// Binary search a sorted slice; `Some(index)` on a hit, else `None`.
pub fn binary_search<T: Ord>(xs: &[T], target: &T) -> Option<usize> {
    let (mut lo, mut hi) = (0, xs.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        match xs[mid].cmp(target) {
            std::cmp::Ordering::Equal => return Some(mid),
            std::cmp::Ordering::Less => lo = mid + 1,
            std::cmp::Ordering::Greater => hi = mid,
        }
    }
    None
}

export function quickSort<T>(xs: T[], cmp: (x: T, y: T) => number): T[] {
  if (xs.length <= 1) return xs.slice();
  const [pivot, ...rest] = xs;
  const left = rest.filter((x) => cmp(x, pivot) < 0);
  const right = rest.filter((x) => cmp(x, pivot) >= 0);
  return [...quickSort(left, cmp), pivot, ...quickSort(right, cmp)];
}

/// Quick sort — partition around the first element, recurse each side.
pub fn quick_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    if xs.len() <= 1 {
        return xs.to_vec();
    }
    let pivot = xs[0].clone();
    let left: Vec<T> = xs[1..].iter().filter(|x| **x < pivot).cloned().collect();
    let right: Vec<T> = xs[1..].iter().filter(|x| **x >= pivot).cloned().collect();
    let mut out = quick_sort(&left);
    out.push(pivot);
    out.extend(quick_sort(&right));
    out
}

export function bfs(adj: Map<string, string[]>, start: string): string[] {
  const order: string[] = [];
  const seen = new Set<string>([start]);
  const queue: string[] = [start];
  while (queue.length) {
    const node = queue.shift()!;
    order.push(node);
    for (const next of adj.get(node) ?? []) {
      if (!seen.has(next)) {
        seen.add(next);
        queue.push(next);
      }
    }
  }
  return order;
}

use std::collections::{HashMap, HashSet, VecDeque};

/// Breadth-first traversal order from `start` over an adjacency map.
pub fn bfs(adj: &HashMap<&str, Vec<&str>>, start: &str) -> Vec<String> {
    let mut order = Vec::new();
    let mut seen = HashSet::from([start]);
    let mut queue = VecDeque::from([start]);
    while let Some(node) = queue.pop_front() {
        order.push(node.to_string());
        for &next in adj.get(node).into_iter().flatten() {
            if seen.insert(next) {
                queue.push_back(next);
            }
        }
    }
    order
}

export function bubbleSort<T>(xs: T[], cmp: (x: T, y: T) => number): T[] {
  const out = xs.slice();
  for (let end = out.length - 1; end > 0; end--) {
    let swapped = false;
    for (let i = 0; i < end; i++) {
      if (cmp(out[i], out[i + 1]) > 0) {
        [out[i], out[i + 1]] = [out[i + 1], out[i]];
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return out;
}

/// Bubble sort — repeatedly swap adjacent out-of-order pairs; stop early once a pass makes no swap.
pub fn bubble_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    let mut out = xs.to_vec();
    let n = out.len();
    for end in (1..n).rev() {
        let mut swapped = false;
        for i in 0..end {
            if out[i] > out[i + 1] {
                out.swap(i, i + 1);
                swapped = true;
            }
        }
        if !swapped {
            break;
        }
    }
    out
}

export function insertionSort<T>(xs: T[], cmp: (x: T, y: T) => number): T[] {
  const out = xs.slice();
  for (let i = 1; i < out.length; i++) {
    const key = out[i];
    let j = i - 1;
    while (j >= 0 && cmp(out[j], key) > 0) {
      out[j + 1] = out[j];
      j--;
    }
    out[j + 1] = key;
  }
  return out;
}

/// Insertion sort — grow a sorted prefix, shifting larger elements right to open a slot.
pub fn insertion_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    let mut out = xs.to_vec();
    for i in 1..out.len() {
        let mut j = i;
        while j > 0 && out[j - 1] > out[j] {
            out.swap(j - 1, j);
            j -= 1;
        }
    }
    out
}

export function heapSort<T>(xs: T[], cmp: (x: T, y: T) => number): T[] {
  const out = xs.slice();
  const n = out.length;
  const siftDown = (start: number, end: number) => {
    let root = start;
    for (;;) {
      const left = 2 * root + 1;
      if (left > end) return;
      const right = left + 1;
      let largest = root;
      if (cmp(out[largest], out[left]) < 0) largest = left;
      if (right <= end && cmp(out[largest], out[right]) < 0) largest = right;
      if (largest === root) return;
      [out[root], out[largest]] = [out[largest], out[root]];
      root = largest;
    }
  };
  for (let i = (n >> 1) - 1; i >= 0; i--) siftDown(i, n - 1);
  for (let end = n - 1; end > 0; end--) {
    [out[0], out[end]] = [out[end], out[0]];
    siftDown(0, end - 1);
  }
  return out;
}

/// Heap sort — build a max-heap in place, then swap the root to the end and re-sift the rest.
pub fn heap_sort<T: Ord + Clone>(xs: &[T]) -> Vec<T> {
    fn sift_down<T: Ord>(a: &mut [T], start: usize, end: usize) {
        let mut root = start;
        loop {
            let left = 2 * root + 1;
            if left > end {
                return;
            }
            let right = left + 1;
            let mut largest = root;
            if a[largest] < a[left] {
                largest = left;
            }
            if right <= end && a[largest] < a[right] {
                largest = right;
            }
            if largest == root {
                return;
            }
            a.swap(root, largest);
            root = largest;
        }
    }
    let mut out = xs.to_vec();
    let n = out.len();
    if n < 2 {
        return out;
    }
    for start in (0..n / 2).rev() {
        sift_down(&mut out, start, n - 1);
    }
    for end in (1..n).rev() {
        out.swap(0, end);
        sift_down(&mut out, 0, end - 1);
    }
    out
}

export function linearSearch<T>(xs: T[], target: T, cmp: (x: T, y: T) => number): number {
  for (let i = 0; i < xs.length; i++) {
    if (cmp(xs[i], target) === 0) return i;
  }
  return -1;
}

/// Linear search — the index of the first element equal to `target`, else `None`.
pub fn linear_search<T: PartialEq>(xs: &[T], target: &T) -> Option<usize> {
    xs.iter().position(|x| x == target)
}

export function dfs(adj: Map<string, [string, number][]>, start: string): string[] {
  const order: string[] = [];
  const seen = new Set<string>();
  const visit = (node: string) => {
    if (seen.has(node)) return;
    seen.add(node);
    order.push(node);
    for (const [next] of adj.get(node) ?? []) visit(next);
  };
  visit(start);
  return order;
}

use std::collections::{HashMap, HashSet};

/// Depth-first traversal order from `start` over a weighted adjacency map (weights ignored).
pub fn dfs(adj: &HashMap<String, Vec<(String, u32)>>, start: &str) -> Vec<String> {
    fn visit(
        adj: &HashMap<String, Vec<(String, u32)>>,
        node: &str,
        seen: &mut HashSet<String>,
        order: &mut Vec<String>,
    ) {
        if !seen.insert(node.to_string()) {
            return;
        }
        order.push(node.to_string());
        if let Some(neighbors) = adj.get(node) {
            for (next, _) in neighbors {
                visit(adj, next, seen, order);
            }
        }
    }
    let mut order = Vec::new();
    let mut seen = HashSet::new();
    visit(adj, start, &mut seen, &mut order);
    order
}

export function dijkstra(adj: Map<string, [string, number][]>, start: string): Map<string, number> {
  const dist = new Map<string, number>([[start, 0]]);
  const visited = new Set<string>();
  for (;;) {
    let node: string | undefined;
    let best = Infinity;
    for (const [n, d] of dist) {
      if (!visited.has(n) && d < best) {
        best = d;
        node = n;
      }
    }
    if (node === undefined) break;
    visited.add(node);
    for (const [next, w] of adj.get(node) ?? []) {
      const nd = best + w;
      if (nd < (dist.get(next) ?? Infinity)) dist.set(next, nd);
    }
  }
  return dist;
}

use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};

/// Dijkstra shortest-path distances from `start` over a non-negative weighted adjacency map.
pub fn dijkstra(adj: &HashMap<String, Vec<(String, u32)>>, start: &str) -> HashMap<String, u32> {
    let mut dist: HashMap<String, u32> = HashMap::from([(start.to_string(), 0)]);
    let mut heap: BinaryHeap<Reverse<(u32, String)>> = BinaryHeap::new();
    heap.push(Reverse((0, start.to_string())));
    while let Some(Reverse((d, node))) = heap.pop() {
        if d > dist.get(&node).copied().unwrap_or(u32::MAX) {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (next, w) in neighbors {
                let nd = d + w;
                if nd < dist.get(next).copied().unwrap_or(u32::MAX) {
                    dist.insert(next.clone(), nd);
                    heap.push(Reverse((nd, next.clone())));
                }
            }
        }
    }
    dist
}

export function aStar(
  adj: Map<string, [string, number][]>,
  start: string,
  goal: string,
  heuristic: (node: string) => number,
): string[] | null {
  const gScore = new Map<string, number>([[start, 0]]);
  const cameFrom = new Map<string, string>();
  const open = new Set<string>([start]);
  while (open.size) {
    let current: string | undefined;
    let best = Infinity;
    for (const n of open) {
      const f = (gScore.get(n) ?? Infinity) + heuristic(n);
      if (f < best) {
        best = f;
        current = n;
      }
    }
    if (current === undefined) break;
    if (current === goal) {
      const path = [current];
      let step = current;
      while (cameFrom.has(step)) {
        step = cameFrom.get(step)!;
        path.unshift(step);
      }
      return path;
    }
    open.delete(current);
    const gCurrent = gScore.get(current) ?? Infinity;
    for (const [next, w] of adj.get(current) ?? []) {
      const tentative = gCurrent + w;
      if (tentative < (gScore.get(next) ?? Infinity)) {
        cameFrom.set(next, current);
        gScore.set(next, tentative);
        open.add(next);
      }
    }
  }
  return null;
}

use std::collections::{HashMap, HashSet};

/// A* shortest path from `start` to `goal`, guided by `heuristic`. Returns the node path
/// (inclusive of both ends) or `None` if `goal` is unreachable.
pub fn a_star(
    adj: &HashMap<String, Vec<(String, u32)>>,
    start: &str,
    goal: &str,
    heuristic: impl Fn(&str) -> u32,
) -> Option<Vec<String>> {
    let mut g_score: HashMap<String, u32> = HashMap::from([(start.to_string(), 0)]);
    let mut came_from: HashMap<String, String> = HashMap::new();
    let mut open: HashSet<String> = HashSet::from([start.to_string()]);
    while !open.is_empty() {
        let current = open
            .iter()
            .min_by_key(|n| {
                g_score.get(*n).copied().unwrap_or(u32::MAX).saturating_add(heuristic(n))
            })
            .cloned()
            .unwrap();
        if current == goal {
            let mut path = vec![current.clone()];
            let mut step = current;
            while let Some(prev) = came_from.get(&step) {
                path.push(prev.clone());
                step = prev.clone();
            }
            path.reverse();
            return Some(path);
        }
        open.remove(&current);
        let g_current = g_score.get(&current).copied().unwrap_or(u32::MAX);
        if let Some(neighbors) = adj.get(&current) {
            for (next, w) in neighbors {
                let tentative = g_current.saturating_add(*w);
                if tentative < g_score.get(next).copied().unwrap_or(u32::MAX) {
                    came_from.insert(next.clone(), current.clone());
                    g_score.insert(next.clone(), tentative);
                    open.insert(next.clone());
                }
            }
        }
    }
    None
}

export function topologicalSort(adj: Map<string, [string, number][]>): string[] | null {
  const indegree = new Map<string, number>();
  const ensure = (n: string) => { if (!indegree.has(n)) indegree.set(n, 0); };
  for (const [node, edges] of adj) {
    ensure(node);
    for (const [next] of edges) {
      ensure(next);
      indegree.set(next, indegree.get(next)! + 1);
    }
  }
  const queue: string[] = [];
  for (const [node, deg] of indegree) if (deg === 0) queue.push(node);
  const order: string[] = [];
  while (queue.length) {
    const node = queue.shift()!;
    order.push(node);
    for (const [next] of adj.get(node) ?? []) {
      const d = indegree.get(next)! - 1;
      indegree.set(next, d);
      if (d === 0) queue.push(next);
    }
  }
  return order.length === indegree.size ? order : null;
}

use std::collections::{HashMap, VecDeque};

/// Kahn's algorithm — a topological ordering of a DAG, or `None` if a cycle is present.
pub fn topological_sort(adj: &HashMap<String, Vec<(String, u32)>>) -> Option<Vec<String>> {
    let mut indegree: HashMap<String, usize> = HashMap::new();
    for (node, edges) in adj {
        indegree.entry(node.clone()).or_insert(0);
        for (next, _) in edges {
            *indegree.entry(next.clone()).or_insert(0) += 1;
        }
    }
    let mut queue: VecDeque<String> = indegree
        .iter()
        .filter(|(_, &d)| d == 0)
        .map(|(n, _)| n.clone())
        .collect();
    let mut order = Vec::new();
    while let Some(node) = queue.pop_front() {
        order.push(node.clone());
        if let Some(edges) = adj.get(&node) {
            for (next, _) in edges {
                let d = indegree.get_mut(next).unwrap();
                *d -= 1;
                if *d == 0 {
                    queue.push_back(next.clone());
                }
            }
        }
    }
    if order.len() == indegree.len() {
        Some(order)
    } else {
        None
    }
}

export function fibonacci(n: number): number {
  if (n < 2) return n;
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    [a, b] = [b, a + b];
  }
  return b;
}

/// The nth Fibonacci number (0-indexed: F0 = 0, F1 = 1), iterated bottom-up.
pub fn fibonacci(n: u64) -> u64 {
    if n < 2 {
        return n;
    }
    let (mut a, mut b) = (0u64, 1u64);
    for _ in 2..=n {
        let next = a + b;
        a = b;
        b = next;
    }
    b
}

export function gcd(a: number, b: number): number {
  let x = Math.abs(a);
  let y = Math.abs(b);
  while (y !== 0) {
    [x, y] = [y, x % y];
  }
  return x;
}

/// Greatest common divisor via the Euclidean algorithm (iterated remainder).
pub fn gcd(mut a: u64, mut b: u64) -> u64 {
    while b != 0 {
        let r = a % b;
        a = b;
        b = r;
    }
    a
}

export interface Complex { re: number; im: number }

export function fft(input: Complex[]): Complex[] {
  const n = input.length;
  if (n <= 1) return input.slice();
  if (n & (n - 1)) throw new Error("fft: length must be a power of two");
  const even = fft(input.filter((_, i) => i % 2 === 0));
  const odd = fft(input.filter((_, i) => i % 2 === 1));
  const out: Complex[] = new Array(n);
  for (let k = 0; k < n / 2; k++) {
    const angle = (-2 * Math.PI * k) / n;
    const tw = { re: Math.cos(angle), im: Math.sin(angle) };
    const o = odd[k];
    const t = { re: tw.re * o.re - tw.im * o.im, im: tw.re * o.im + tw.im * o.re };
    out[k] = { re: even[k].re + t.re, im: even[k].im + t.im };
    out[k + n / 2] = { re: even[k].re - t.re, im: even[k].im - t.im };
  }
  return out;
}

/// Recursive radix-2 Cooley–Tukey FFT over complex samples `(re, im)`.
/// `input.len()` must be a power of two.
pub fn fft(input: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = input.len();
    if n <= 1 {
        return input.to_vec();
    }
    assert!(n & (n - 1) == 0, "fft: length must be a power of two");
    let even = fft(&input.iter().step_by(2).copied().collect::<Vec<_>>());
    let odd = fft(&input.iter().skip(1).step_by(2).copied().collect::<Vec<_>>());
    let mut out = vec![(0.0, 0.0); n];
    for k in 0..n / 2 {
        let angle = -2.0 * std::f64::consts::PI * k as f64 / n as f64;
        let (tw_re, tw_im) = (angle.cos(), angle.sin());
        let (o_re, o_im) = odd[k];
        let t = (tw_re * o_re - tw_im * o_im, tw_re * o_im + tw_im * o_re);
        let (e_re, e_im) = even[k];
        out[k] = (e_re + t.0, e_im + t.1);
        out[k + n / 2] = (e_re - t.0, e_im - t.1);
    }
    out
}
